"""Capture independent current-main baseline findings with exact source and transcription hashes."""
from pathlib import Path
import hashlib,csv,json,subprocess,io,sys
root=Path(__file__).resolve().parent
repo=Path(sys.argv[1]) if len(sys.argv)>1 else Path(subprocess.check_output(['git','rev-parse','--show-toplevel'],text=True).strip())
pin='51914da4b58fb425b710e070ef10c20da6f119a4'
def read(p):return subprocess.check_output(['git','-C',str(repo),'show',pin+':'+p])
def h(b):return hashlib.sha256(b).hexdigest()
rows={}
def add(n,stage,finding,followup,paths,extra={}):
 rows['EO:'+str(n)]={'stage':stage,'finding':finding,'open_work':followup,'source_paths_sha256':{p:h(read(p)) for p in paths},**extra}
early=['jobs/lachmann/output/RESIDUAL.csv','jobs/lachmann/output/CONFIRMATIONS.jsonl']
for n,p,comment in [(1929,'PT1-1914-EO-1929.pdf','Single printed order, Bonita Administrative Site, Wilson, 4 May 1914, No. 1929; corrected E ½ NE ¼ and mineral survey exception. Temporary withdrawal and Forest Service reservation are not an end.'),(3405,'1921-EO-3405.pdf','Single printed order, Wilson, 12 February 1921, No. 3405; SW¼ SW¼ (Lot 7), Sec. 6; 39.41 acres; temporary withdrawal with statutory exception and ranger-station reservation.'),(4195,'PT1-1925-EO-4195.pdf','Coolidge, April 10, 1925, No. 4195. Text page and page 2 identified Forest Service map checked. Road excluded, joint administration, war/defense authority and inconsistent-statute proviso retained. Attachment itself is part of the reading, not an OCR paragraph.')]:
 pdf='ProQuest Pre-1937 Orders/'+p
 add(n,'complete_identified_replica_pages__working_transcription_producer_only',comment,'Independent verification of the transcription and associated scan; original replacement, quotation recheck, and legal work remain.',early+['jobs/pinakes-proquest-ingest/output/ORDERS.csv','jobs/pinakes-proquest-ingest/output/texts/EO_'+str(n)+'.txt',pdf],{'transcription_path':'baseline-pages/EO_'+str(n)+'-working.txt','transcription_sha256':h((root/'baseline-pages'/f'EO_{n}-working.txt').read_bytes()),'pages':2 if n==4195 else 1})
add(2314,'misattribution_rejected__correction_lead','Registry subject is Annie E. Hudson; nominally EO_2314.txt concerns Monroe Ryles. Different file EO_2312.txt actually contains subject-matched Hudson text on Feb 11. Three same-day exemptions paired mechanically by number, not independently identified.','Inspect original printed 1916 CSR p. 114 (PDF p. 152), serial set 07215_00_00-002-1488-0000; body plus project index needed before relabeling. Official PDF opening returned an access error; no accepted text. No performance fact inferred.',early+['jobs/csc-annual-reports/output/CITATION_RESULTS.csv','jobs/csc-annual-reports/output/texts/EO_2314.txt','jobs/csc-annual-reports/output/texts/EO_2312.txt'])
add(922,'text_lead_no_page','Mirror presents date, signature and replacement eligibility rule; it cites 1908 Civil Service Report p. 128. No checked page, and first paragraph insert differs slightly from restated rule.','Confirm against report’s text and page boundaries; official PDF opening returned access error. No status conclusion.',early+['jobs/wikisource-texts/output/texts/EO_922.txt','jobs/csc-annual-reports/output/REPORTS_FETCHED.csv'])
add(1070,'text_lead_no_page','Complete-looking Shaw Island mirror gives metes and bounds with apparent typographical errors plus a note on later EO 1097 correction. May 1909 Government Printing Office catalog corroborates subject but is not the order.','Check historical base pages and later correction; separate original west bearing from later east; neither a first end nor closure inferred.',early+['jobs/wikisource-texts/output/texts/EO_1070.txt'],{'corroborating_catalog':'https://www.govinfo.gov/content/pkg/GOVPUB-GP3-b2ab4bed829ff7bcf5755279580aca97/pdf/GOVPUB-GP3-b2ab4bed829ff7bcf5755279580aca97.pdf'})
def direct(n,actors):
 return [f'jobs/fr-originals/output/texts/EO_{k}.txt' for k in [n]+actors]+[f'jobs/status-history/output/histories/EO_{n}.json']
add(13457,'original_command_and_bounded_activity_lead__no_cutoff_answer','Original 73 FR 6417–18 imposes prospective earmark duties including publishing qualifying written communications within 30 days of receipt, subject to a confidentiality exception. Held history has zero later event IDs and empty catalog note. Agency compliance page quotes directive but correspondence stops at FY2011; does not establish cutoff status.','Check section-level post-issue implementation, contrary laws/actors and affirmative predicate at 2026-10-14. No whole-case YES or NO.',direct(13457,[]),{'agency_lead':'https://comptroller.war.gov/Budget-Execution/earmarks/'})
add(13396,'direct_revocation_with_exact_clock_and_savings__bounded_finding','EO 13739 revokes EO 13396 and terminates its emergency effective 2016-09-14 08:00 EDT under section 3. Section 1 saves pending proceedings, acts already committed, accrued rights/duties and incurred penalties. OFAC confirms date, operation and removal of regulations; no inference all consequences ended.','Audit earlier changes, annual continuations, sanctions releases, savings and revival/contrary evidence through cutoff before a first-ending or whole-claim finding.',direct(13396,[13739]),{'corroborating_official':'https://www.govinfo.gov/content/pkg/FR-2017-11-13/pdf/FR-2017-11-13.pdf','actor_official':'https://www.govinfo.gov/content/pkg/FR-2016-09-16/pdf/2016-22454.pdf'})
add(12941,'direct_revocation_no_express_effective_clock__bounded_finding','EO 13717 sec. 5 expressly revokes EO 12941; signed 2016-02-02, filed Feb 4, published Feb 5. Section 8 preserves statutory/agency authorities; successor duties belong to EO 13717. Do not convert signature into an express effectiveness clause.','Compare original’s completed reporting/cost functions with continuing technical standards and intervening amendments; no claim about first exhaustion or certified status.',direct(12941,[13717]),{'official_annual_compilation':'https://www.govinfo.gov/content/pkg/CFR-2017-title3-vol1/pdf/CFR-2017-title3-vol1-eo13717.pdf'})
result={'pin':pin,'cutoff':'2026-10-14','baseline':'Existing per-order workflow plus competent source reading. No novel model automation. All 6 A plus all 3 B. No experimental work inspected when composing. No human, cross-family or science certification. No changes to main.','rows':rows}
(root/'baseline-results.json').write_text(json.dumps(result,indent=2)+'\n')
